        for u, v in edges:
            g[u].append(v)
        fin = [0] * n
        stk = [(0, 0)]
        while stk:
            i, state = stk.pop()
            if state == 0:
                if not g[i]:
                    fin[i] = baseTime[i]
                else:
                    stk.append((i, 1))
                    for j in g[i]:
                        stk.append((j, 0))
            else:
                earliest, latest = inf, -inf
                for j in g[i]:
                    a = fin[j]
                    earliest = min(earliest, a)
                    latest = max(latest, a)
                own = (latest - earliest) + baseTime[i]
                fin[i] = latest + own
        return fin[0]

class Solution {
    public long finishTime(int n, int[][] edges, int[] baseTime) {
        List<Integer>[] g = new List[n];
        Arrays.setAll(g, k -> new ArrayList<>());
        for (int[] e : edges) {
            g[e[0]].add(e[1]);
        }
        long[] fin = new long[n];
        Deque<int[]> stk = new ArrayDeque<>();
        stk.push(new int[] {0, 0});
        while (!stk.isEmpty()) {
            int[] cur = stk.pop();
            int i = cur[0], state = cur[1];
            if (state == 0) {
                if (g[i].isEmpty()) {
                    fin[i] = baseTime[i];
                } else {
                    stk.push(new int[] {i, 1});
                    for (int j : g[i]) {
                        stk.push(new int[] {j, 0});
                    }
                }
            } else {
                long earliest = Long.MAX_VALUE;
                long latest = Long.MIN_VALUE;
                for (int j : g[i]) {
                    earliest = Math.min(earliest, fin[j]);
                    latest = Math.max(latest, fin[j]);
                }
                long ownDuration = (latest - earliest) + baseTime[i];
                fin[i] = latest + ownDuration;
            }
        }
        return fin[0];
    }
}

